class GfG {

    static ArrayList<Integer> search(int[] a, int[] b) {
        int n = a.length, m = b.length;
        ArrayList<Integer> res = new ArrayList<>();

        // Iterate over all possible 
        // starting indices
        for (int i = 0; i <= n - m; i++) {
            boolean isSame = true;

            // Check if b matches starting 
            // from index i in a
            for (int j = 0; j < m; j++) {
                if (a[i + j] != b[j]) {
                    isSame = false;
                    break;
                }
            }

            // If all elements matched, 
